# Data Studio ---------------------------------------------------------------
#
# Data preparation layer introduced in Wave 1.  It never replaces the command
# engine: every structural change is a command generated by the builders in
# `command-builders-data.R` and executed by `run_command()`.  The registry,
# dictionary, checkpoints and selection are session metadata that make the
# grid usable without hiding the R code.

# Registry -------------------------------------------------------------------

dataset_class <- function(x) {
  classes <- class(x)
  if (length(classes) == 0L) typeof(x) else classes[[1L]]
}

dataset_metadata_from_env <- function(state, name) {
  if (!exists(name, envir = state$env, inherits = FALSE)) return(NULL)
  df <- get(name, envir = state$env, inherits = FALSE)
  if (!is.data.frame(df)) return(NULL)
  cells <- as.numeric(nrow(df)) * as.numeric(ncol(df))
  list(
    name = name,
    rows = as.integer(nrow(df)),
    cols = as.integer(ncol(df)),
    classes = vapply(df, dataset_class, character(1)),
    source = "session",
    modified = Sys.time(),
    editable = cells <= (state$options$edit_threshold %||% 0L)
  )
}

#' Register a data frame in the session registry
#' @keywords internal
dataset_register <- function(state, name, source = NULL, refresh = FALSE) {
  if (is.null(name) || !nzchar(name)) return(invisible(NULL))
  meta <- dataset_metadata_from_env(state, name)
  if (is.null(meta)) return(invisible(NULL))

  existing <- (state$datasets %||% list())[[name]]
  if (!is.null(existing)) {
    meta$source <- existing$source %||% meta$source
    meta$modified <- existing$modified %||% meta$modified
  }
  if (!is.null(source) && nzchar(source)) meta$source <- source
  if (isTRUE(refresh)) meta$modified <- Sys.time()

  state$datasets[[name]] <- meta
  invisible(meta)
}

#' Remove a data frame from the registry without deleting the R object
#' @keywords internal
dataset_unregister <- function(state, name) {
  if (is.null(name) || is.null(state$datasets[[name]])) return(invisible(FALSE))
  state$datasets[[name]] <- NULL
  invisible(TRUE)
}

#' Record where a data set came from
#' @keywords internal
dataset_set_source <- function(state, name, source) {
  if (is.null(state$datasets[[name]])) dataset_register(state, name)
  if (is.null(state$datasets[[name]])) return(invisible(NULL))
  state$datasets[[name]]$source <- source
  invisible(state$datasets[[name]])
}

#' Session data set registry
#'
#' The registry is reconciled with the evaluation environment on every call:
#' data frames created by the console or by a script are picked up, and
#' objects removed from R disappear from the registry.  Returning a data frame
#' makes the registry easy to render.
#' @keywords internal
dataset_registry <- function(state) {
  objects <- list_data_sets(state)
  state$datasets <- (state$datasets %||% list())[
    intersect(names(state$datasets %||% list()), objects)
  ]
  for (name in objects) {
    dataset_register(state, name)
  }
  entries <- state$datasets
  if (length(entries) == 0L) {
    return(data.frame(
      name = character(), rows = integer(), cols = integer(),
      classes = character(), source = character(), modified = character(),
      editable = logical(), active = logical(), cells = numeric(),
      stringsAsFactors = FALSE
    ))
  }
  active <- active_dataset(state)
  data.frame(
    name = vapply(entries, function(entry) entry$name, character(1)),
    rows = vapply(entries, function(entry) as.integer(entry$rows), integer(1)),
    cols = vapply(entries, function(entry) as.integer(entry$cols), integer(1)),
    classes = vapply(entries, function(entry) {
      paste(names(entry$classes), entry$classes, sep = ":", collapse = ", ")
    }, character(1)),
    source = vapply(entries, function(entry) entry$source %||% "session",
                    character(1)),
    modified = vapply(entries, function(entry) {
      format(entry$modified %||% Sys.time(), "%Y-%m-%d %H:%M")
    }, character(1)),
    editable = vapply(entries, function(entry) isTRUE(entry$editable),
                      logical(1)),
    active = vapply(entries, function(entry) identical(entry$name, active),
                    logical(1)),
    cells = vapply(entries, function(entry) {
      as.numeric(entry$rows) * as.numeric(entry$cols)
    }, numeric(1)),
    stringsAsFactors = FALSE
  )
}

#' Metadata for one registered data set
#' @keywords internal
dataset_metadata <- function(state, name = active_dataset(state)) {
  if (is.null(name)) return(NULL)
  if (is.null((state$datasets %||% list())[[name]])) dataset_register(state, name)
  (state$datasets %||% list())[[name]]
}

#' Activate a registered data set
#' @keywords internal
dataset_activate <- function(state, name) {
  if (is.null(name) || !nzchar(name)) {
    return(invisible(NULL))
  }
  dataset_register(state, name)
  active_dataset(state, name)
  invisible(name)
}

#' Dataset choices for selectors
#' @keywords internal
dataset_choices <- function(state) {
  registry <- dataset_registry(state)
  if (nrow(registry) == 0L) return(character())
  stats::setNames(registry$name, registry$name)
}

#' Human-readable data set label
#' @keywords internal
dataset_label <- function(state, name) {
  meta <- dataset_metadata(state, name)
  if (is.null(meta)) return(name %||% "")
  sprintf("%s (%d x %d)", meta$name, meta$rows, meta$cols)
}

# Data dictionary ------------------------------------------------------------

dictionary_entry <- function(state, dataset_name, variable) {
  if (is.null(dataset_name) || is.null(variable)) return(list())
  dataset_entries <- state$data_dictionary[[dataset_name]] %||% list()
  entry <- dataset_entries[[variable]]
  entry %||% list()
}

#' Read the label and units of a variable
#' @keywords internal
variable_label <- function(state, dataset_name = active_dataset(state),
                           variable) {
  if (is.null(dataset_name)) {
    return(list(label = "", units = "", description = ""))
  }
  df <- get0(dataset_name, envir = state$env, inherits = FALSE)
  if (is.null(df) || !is.data.frame(df) || !variable %in% names(df)) {
    return(list(label = "", units = "", description = ""))
  }
  entry <- dictionary_entry(state, dataset_name, variable)
  x <- df[[variable]]
  list(
    label = entry$label %||% attr(x, "label", exact = TRUE) %||% "",
    units = entry$units %||% attr(x, "units", exact = TRUE) %||% "",
    description = entry$description %||%
      attr(x, "description", exact = TRUE) %||% ""
  )
}

#' Set label, units and description for a variable
#'
#' The attributes on the data frame are updated immediately so that the grid,
#' the inspector and any later command agree.  The matching command is produced
#' by `cmd_set_variable_label()` and is what the UI writes to the log.
#' @keywords internal
set_variable_label <- function(state, dataset_name = active_dataset(state),
                               variable, label = NULL, units = NULL,
                               description = NULL) {
  if (is.null(dataset_name)) {
    stop("There is no active data set.", call. = FALSE)
  }
  df <- get0(dataset_name, envir = state$env, inherits = FALSE)
  if (is.null(df) || !is.data.frame(df)) {
    stop("There is no active data set.", call. = FALSE)
  }
  if (!variable %in% names(df)) {
    stop(sprintf("Unknown variable: %s", variable), call. = FALSE)
  }

  entry <- dictionary_entry(state, dataset_name, variable)
  if (!is.null(label)) entry$label <- label
  if (!is.null(units)) entry$units <- units
  if (!is.null(description)) entry$description <- description
  state$data_dictionary[[dataset_name]][[variable]] <- entry

  x <- df[[variable]]
  if (!is.null(label)) attr(x, "label") <- label
  if (!is.null(units)) attr(x, "units") <- units
  if (!is.null(description)) attr(x, "description") <- description
  df[[variable]] <- x
  assign(dataset_name, df, envir = state$env)
  dataset_register(state, dataset_name)
  state_touch(state)
  invisible(entry)
}

#' Data dictionary as a data frame
#' @keywords internal
dictionary_table <- function(state, dataset_name = active_dataset(state)) {
  if (is.null(dataset_name)) {
    return(data.frame(
      variable = character(), class = character(), label = character(),
      units = character(), description = character(), missing = integer(),
      stringsAsFactors = FALSE
    ))
  }
  df <- get0(dataset_name, envir = state$env, inherits = FALSE)
  if (is.null(df) || !is.data.frame(df)) {
    return(data.frame(
      variable = character(), class = character(), label = character(),
      units = character(), description = character(), missing = integer(),
      stringsAsFactors = FALSE
    ))
  }
  rows <- lapply(names(df), function(variable) {
    meta <- variable_label(state, dataset_name, variable)
    data.frame(
      variable = variable,
      class = dataset_class(df[[variable]]),
      label = meta$label %||% "",
      units = meta$units %||% "",
      description = meta$description %||% "",
      missing = sum(is.na(df[[variable]])),
      stringsAsFactors = FALSE
    )
  })
  do.call(rbind, rows)
}

#' Dictionary rows ready for export
#' @keywords internal
dictionary_export <- function(state, dataset_name = active_dataset(state)) {
  dictionary_table(state, dataset_name)
}

# Checkpoints ----------------------------------------------------------------

checkpoint_label_default <- function(label) {
  label <- trim_blanks(label %||% "")
  if (!nzchar(label)) "Manual checkpoint" else label
}

checkpoint_bytes <- function(data) {
  as.numeric(utils::object.size(data))
}

#' Create a checkpoint of a data set
#'
#' Checkpoints are session snapshots, not commands.  They are capped by count
#' and by total memory; when a data frame is larger than the memory cap no
#' checkpoint is created and `state$last_checkpoint_skip` explains why.
#' @keywords internal
checkpoint_create <- function(state, label = "",
                              dataset_name = active_dataset(state)) {
  if (is.null(dataset_name)) return(invisible(NULL))
  df <- get0(dataset_name, envir = state$env, inherits = FALSE)
  if (is.null(df) || !is.data.frame(df)) return(invisible(NULL))

  bytes <- checkpoint_bytes(df)
  max_bytes <- as.numeric(state$options$checkpoint_max_bytes %||%
                            (50 * 1024^2))
  if (bytes > max_bytes) {
    state$last_checkpoint_skip <- list(
      dataset = dataset_name,
      bytes = bytes,
      reason = tr("The data set is larger than the checkpoint memory cap.")
    )
    return(invisible(NULL))
  }

  state$checkpoint_counter <- as.integer(state$checkpoint_counter %||% 0L) + 1L
  entry <- list(
    id = sprintf("ckpt-%04d", state$checkpoint_counter),
    dataset = dataset_name,
    time = Sys.time(),
    label = checkpoint_label_default(label),
    data = df,
    rows = as.integer(nrow(df)),
    cols = as.integer(ncol(df)),
    bytes = bytes
  )

  checkpoints <- c(list(entry), state$checkpoints %||% list())
  max_count <- as.integer(state$options$checkpoint_max %||% 20L)
  checkpoints <- utils::head(checkpoints, max_count)

  total <- cumsum(vapply(checkpoints, function(item) item$bytes, numeric(1)))
  keep <- which(total <= max_bytes)
  if (length(keep) > 0L) checkpoints <- checkpoints[keep]
  state$checkpoints <- checkpoints
  state_touch(state)
  invisible(entry)
}

#' List checkpoints
#' @keywords internal
checkpoint_list <- function(state, dataset_name = NULL) {
  checkpoints <- state$checkpoints %||% list()
  if (!is.null(dataset_name)) {
    checkpoints <- Filter(function(item) {
      identical(item$dataset, dataset_name)
    }, checkpoints)
  }
  if (length(checkpoints) == 0L) {
    return(data.frame(
      id = character(), dataset = character(), time = character(),
      label = character(), rows = integer(), cols = integer(),
      size = character(), stringsAsFactors = FALSE
    ))
  }
  data.frame(
    id = vapply(checkpoints, function(item) item$id, character(1)),
    dataset = vapply(checkpoints, function(item) item$dataset, character(1)),
    time = vapply(checkpoints, function(item) {
      format(item$time %||% Sys.time(), "%H:%M:%S")
    }, character(1)),
    label = vapply(checkpoints, function(item) item$label %||% "",
                   character(1)),
    rows = vapply(checkpoints, function(item) as.integer(item$rows),
                  integer(1)),
    cols = vapply(checkpoints, function(item) as.integer(item$cols),
                  integer(1)),
    size = vapply(checkpoints, function(item) {
      sprintf("%.1f MB", item$bytes / (1024^2))
    }, character(1)),
    stringsAsFactors = FALSE
  )
}

#' Restore a checkpoint
#'
#' The restore is a session operation: it does not append a command to the
#' script log.  A note is added to the structured history so that the user can
#' still see what happened.
#' @keywords internal
checkpoint_restore <- function(state, id) {
  entry <- NULL
  for (item in state$checkpoints %||% list()) {
    if (identical(item$id, id)) {
      entry <- item
      break
    }
  }
  if (is.null(entry)) return(invisible(FALSE))

  assign(entry$dataset, entry$data, envir = state$env)
  dataset_register(state, entry$dataset, refresh = TRUE)
  if (identical(active_dataset(state), entry$dataset)) {
    active_dataset(state, entry$dataset)
  }
  if (is.function(history_add)) {
    history_add(state, history_entry(
      id = history_next_id(state),
      time = Sys.time(),
      source = "checkpoint",
      command = sprintf("# checkpoint restored: %s", entry$label),
      status = "ok",
      output = sprintf(tr("Restored %s at %s"), entry$dataset, entry$id)
    ))
  }
  state_touch(state)
  invisible(TRUE)
}

#' Remove one checkpoint or all of them
#' @keywords internal
checkpoint_clear <- function(state, id = NULL) {
  if (is.null(id)) {
    state$checkpoints <- list()
  } else {
    state$checkpoints <- Filter(function(item) {
      !identical(item$id, id)
    }, state$checkpoints %||% list())
  }
  state_touch(state)
  invisible(TRUE)
}

# Selection ------------------------------------------------------------------

#' Current data selection
#' @keywords internal
data_selection <- function(state) {
  selection <- state$data_selection
  current <- active_dataset(state)
  if (is.null(selection) || !identical(selection$dataset, current)) {
    return(list(dataset = current, rows = integer(), columns = character(),
                expression = ""))
  }
  selection
}

#' Set the data selection
#' @keywords internal
set_data_selection <- function(state, rows = NULL, columns = NULL,
                               expression = NULL,
                               dataset = active_dataset(state)) {
  if (is.null(dataset)) return(invisible(NULL))
  df <- dataset(state)
  if (is.null(df)) return(invisible(NULL))

  rows <- rows %||% integer()
  rows <- rows[!is.na(rows)]
  columns <- columns %||% character()
  columns <- intersect(columns, names(df))
  expression <- trim_blanks(expression %||% "")

  if (length(rows) == 0L && length(columns) == 0L && !nzchar(expression)) {
    state$data_selection <- NULL
    return(invisible(NULL))
  }

  state$data_selection <- list(
    dataset = dataset,
    rows = rows,
    columns = columns,
    expression = expression
  )
  invisible(state$data_selection)
}

#' Clear the data selection
#'
#' Selection changes deliberately do not call `state_touch()`: the Shiny layer
#' keeps its own selection revision so that the grid is not re-rendered (and
#' the selected rows are not lost) when the selection changes.
#' @keywords internal
clear_data_selection <- function(state) {
  state$data_selection <- NULL
  invisible(NULL)
}

#' Selection label for the toolbar
#' @keywords internal
selection_summary <- function(state) {
  selection <- data_selection(state)
  parts <- character()
  if (length(selection$rows) > 0L) {
    parts <- c(parts, sprintf(tr("%d row(s)"), length(selection$rows)))
  }
  if (length(selection$columns) > 0L) {
    parts <- c(parts, sprintf(tr("%d column(s)"), length(selection$columns)))
  }
  if (nzchar(selection$expression %||% "")) {
    parts <- c(parts, sprintf(tr("filter: %s"), selection$expression))
  }
  if (length(parts) == 0L) tr("No selection") else paste(parts, collapse = " - ")
}

#' R expression for the selected row indices
#' @keywords internal
selection_expression <- function(state) {
  selection <- data_selection(state)
  if (nzchar(selection$expression %||% "")) return(selection$expression)
  rows <- selection$rows
  if (length(rows) == 0L) return("")
  if (is.numeric(rows)) {
    return(paste0("c(", paste(as.integer(rows), collapse = ", "), ")"))
  }
  paste0("c(", paste0(r_quote_data(rows), collapse = ", "), ")")
}

#' Command that turns the current selection into a new data set
#' @keywords internal
selection_subset_command <- function(state, new_name,
                                     dataset_name = active_dataset(state)) {
  if (is.null(dataset_name) || !nzchar(new_name)) return(NULL)
  selection <- data_selection(state)
  variables <- selection$columns
  select <- if (length(variables) == 0L) {
    ""
  } else {
    paste0("c(", paste0(r_quote_data(variables), collapse = ", "),
           "), drop = FALSE")
  }

  if (nzchar(selection$expression %||% "")) {
    return(cmd_subset_dataset(
      dataset_name, new_name,
      variables = if (length(variables) > 0L) variables else NULL,
      cases = selection$expression
    ))
  }
  if (length(selection$rows) == 0L) return(NULL)

  rows <- if (is.numeric(selection$rows)) {
    paste(as.integer(selection$rows), collapse = ", ")
  } else {
    paste0(r_quote_data(selection$rows), collapse = ", ")
  }
  suffix <- if (nzchar(select)) paste0(", ", select) else ", drop = FALSE"
  sprintf("%s <- %s[c(%s)%s]", new_name, dataset_name, rows, suffix)
}

# Column profile -------------------------------------------------------------

#' Describe one variable
#'
#' Pure with respect to R: it reads the data set from the state, computes the
#' profile and never writes to the log or to the environment.
#' @keywords internal
column_profile <- function(state, dataset_name = active_dataset(state),
                           variable) {
  if (is.null(dataset_name)) return(NULL)
  df <- get0(dataset_name, envir = state$env, inherits = FALSE)
  if (is.null(df) || !is.data.frame(df) || !variable %in% names(df)) {
    return(NULL)
  }
  x <- df[[variable]]
  meta <- variable_label(state, dataset_name, variable)
  values <- x[!is.na(x)]

  type <- if (inherits(x, "Date") || inherits(x, "POSIXt")) {
    "date"
  } else if (is.numeric(x)) {
    "numeric"
  } else if (is.factor(x)) {
    "factor"
  } else if (is.logical(x)) {
    "logical"
  } else {
    "character"
  }

  profile <- list(
    dataset = dataset_name,
    variable = variable,
    class = dataset_class(x),
    type = type,
    label = meta$label %||% "",
    units = meta$units %||% "",
    description = meta$description %||% "",
    n = length(x),
    missing = sum(is.na(x)),
    unique = length(unique(values)),
    stats = NULL,
    levels = NULL,
    histogram = NULL
  )

  if (type %in% c("numeric", "date") && length(values) > 0L) {
    numbers <- if (inherits(values, "Date")) as.numeric(values) else values
    profile$stats <- list(
      min = min(numbers),
      max = max(numbers),
      mean = mean(numbers),
      median = stats::median(numbers),
      sd = if (length(numbers) > 1L) stats::sd(numbers) else NA_real_,
      q1 = unname(stats::quantile(numbers, 0.25, na.rm = TRUE)),
      q3 = unname(stats::quantile(numbers, 0.75, na.rm = TRUE))
    )
    if (type == "numeric" && length(unique(numbers)) > 1L) {
      breaks <- tryCatch(
        graphics::hist(numbers, plot = FALSE, breaks = "Sturges"),
        error = function(e) NULL
      )
      if (!is.null(breaks)) {
        profile$histogram <- list(
          breaks = breaks$breaks,
          counts = breaks$counts,
          mids = breaks$mids
        )
      }
    }
  } else if (type %in% c("numeric", "date")) {
    profile$stats <- list(
      min = NA_real_, max = NA_real_, mean = NA_real_, median = NA_real_,
      sd = NA_real_, q1 = NA_real_, q3 = NA_real_
    )
  } else if (length(values) > 0L || type %in% c("factor", "logical", "character")) {
    labels <- if (is.factor(values)) as.character(values) else as.character(values)
    counts <- sort(table(labels), decreasing = TRUE)
    profile$levels <- data.frame(
      value = names(counts),
      count = as.integer(counts),
      stringsAsFactors = FALSE
    )
    rownames(profile$levels) <- NULL
  }

  profile
}

#' One-line profile summary
#' @keywords internal
profile_summary <- function(profile) {
  if (is.null(profile)) return("")
  sprintf("%s: %s, %d values, %d missing, %d unique",
          profile$variable, profile$type, profile$n, profile$missing,
          profile$unique)
}

# Missingness ----------------------------------------------------------------

#' Per-variable missingness
#' @keywords internal
data_missingness <- function(state, dataset_name = active_dataset(state)) {
  if (is.null(dataset_name)) {
    return(data.frame(
      variable = character(), missing = integer(), percent = numeric(),
      stringsAsFactors = FALSE
    ))
  }
  df <- get0(dataset_name, envir = state$env, inherits = FALSE)
  if (is.null(df) || !is.data.frame(df)) {
    return(data.frame(
      variable = character(), missing = integer(), percent = numeric(),
      stringsAsFactors = FALSE
    ))
  }
  missing <- vapply(df, function(x) sum(is.na(x)), integer(1))
  data.frame(
    variable = names(df),
    missing = unname(missing),
    percent = if (nrow(df) > 0L) 100 * missing / nrow(df) else rep(0, ncol(df)),
    stringsAsFactors = FALSE
  )
}

# Import preview -------------------------------------------------------------

detect_delimiter <- function(path) {
  line <- tryCatch(readLines(path, n = 1L, warn = FALSE),
                   error = function(e) character())
  if (length(line) == 0L || !nzchar(line[[1L]])) return(",")
  candidates <- c(",", ";", "\t", "|")
  counts <- vapply(candidates, function(delimiter) {
    lengths(regmatches(line[[1L]],
                       gregexpr(delimiter, line[[1L]], fixed = TRUE)))
  }, integer(1))
  if (max(counts) == 0L) "," else candidates[[which.max(counts)]]
}

delimiter_code <- function(delimiter) {
  switch(
    delimiter,
    auto = NULL,
    commas = ",",
    semicolons = ";",
    tabs = "\t",
    whitespace = "",
    "," = ",", ";" = ";", "\t" = "\t",
    ","
  )
}

# A literal tab inside a generated R string is valid but hard to read.
delimiter_source <- function(delimiter) {
  if (identical(delimiter, "\t")) "\\t" else delimiter
}

#' Parse a value vector with a conservative type guess
#' @keywords internal
suggest_column_type <- function(x) {
  values <- x[!is.na(x) & nzchar(as.character(x))]
  if (length(values) == 0L) return("empty")
  text <- as.character(values)
  numbers <- suppressWarnings(as.numeric(text))
  if (!anyNA(numbers)) {
    if (all(numbers == as.integer(numbers), na.rm = TRUE)) return("integer")
    return("numeric")
  }
  upper <- toupper(text)
  if (all(upper %in% c("TRUE", "FALSE", "T", "F"))) return("logical")
  dates <- tryCatch(suppressWarnings(as.Date(text)), error = function(e) NULL)
  if (!is.null(dates) && !anyNA(dates)) return("date")
  "character"
}

#' Column type proposal for an imported preview
#' @keywords internal
suggest_column_types <- function(df) {
  stats::setNames(
    vapply(df, suggest_column_type, character(1)),
    names(df)
  )
}

#' Preview an import file
#' @keywords internal
preview_import_file <- function(path, delimiter = NULL, header = TRUE,
                                rows = 20L, quote = "\"", dec = ".",
                                na.strings = c("NA", ""),
                                encoding = "unknown") {
  if (is.null(path) || !nzchar(path) || !file.exists(path)) {
    return(list(ok = FALSE, error = tr("File not found."), data = NULL))
  }

  extension <- tolower(tools::file_ext(path))
  if (extension %in% c("xlsx", "xls")) {
    if (!requireNamespace("readxl", quietly = TRUE)) {
      return(list(ok = FALSE,
                  error = tr("The readxl package is required for Excel files."),
                  data = NULL))
    }
    data <- tryCatch(
      as.data.frame(readxl::read_excel(path, n_max = rows)),
      error = function(e) e
    )
    if (inherits(data, "error")) {
      return(list(ok = FALSE, error = conditionMessage(data), data = NULL))
    }
    return(list(ok = TRUE, error = NULL, data = data,
                delimiter = NA_character_,
                types = suggest_column_types(data),
                rows = nrow(data)))
  }

  if (is.null(delimiter)) delimiter <- detect_delimiter(path)
  data <- tryCatch(
    utils::read.table(
      path, sep = delimiter, header = isTRUE(header), nrows = rows,
      stringsAsFactors = FALSE, quote = quote, dec = dec,
      na.strings = na.strings, comment.char = "", fill = TRUE,
      check.names = FALSE
    ),
    error = function(e) e
  )
  if (inherits(data, "error")) {
    return(list(ok = FALSE, error = conditionMessage(data), data = NULL))
  }
  list(
    ok = TRUE, error = NULL, data = data, delimiter = delimiter,
    types = suggest_column_types(data), rows = nrow(data)
  )
}

import_storage_dir <- function() {
  path <- file.path(path.expand("~"), ".RcmdrShiny", "files")
  if (!dir.exists(path)) dir.create(path, recursive = TRUE, showWarnings = FALSE)
  path
}

#' Copy an uploaded file to a durable location
#' @keywords internal
store_import_file <- function(path, original_name = NULL) {
  if (is.null(path) || !file.exists(path)) return(NULL)
  name <- original_name %||% basename(path)
  stamp <- format(Sys.time(), "%Y%m%d-%H%M%S")
  target <- file.path(import_storage_dir(), paste0(stamp, "-", name))
  if (!file.copy(path, target, overwrite = TRUE)) return(NULL)
  target
}

#' Import wizard dialog
#' @keywords internal
data_import_dialog <- function() {
  id <- "dataImportWizard"
  ns <- function(x) paste0(id, "_", x)
  defaults <- list(
    dsname = "ImportedData", header = TRUE, delimiter = "auto",
    stringsAsFactors = TRUE
  )

  dialog_spec(
    id = id,
    title = tr("Import data with preview"),
    help = "read.table",
    preview = FALSE,
    ui = function(state, memory) {
      m <- utils::modifyList(defaults, memory %||% list())
      htmltools::tagList(
        fileInput(
          ns("upload"), tr("File to import"),
          accept = c(".csv", ".txt", ".tsv", ".dat", ".xlsx", ".xls")
        ),
        entry_input(ns("dsname"), tr("Name for the new data set:"),
                    m$dsname),
        checkbox_input(ns("header"), tr("Variable names in the first row"),
                       m$header),
        radio_input(
          ns("delimiter"), tr("Field separator"),
          c("Detect automatically" = "auto", "Commas" = "commas",
            "Semicolons" = "semicolons", "Tabs" = "tabs",
            "White space" = "whitespace"),
          m$delimiter
        ),
        checkbox_input(
          ns("stringsAsFactors"),
          tr("Convert character variables to factors"),
          m$stringsAsFactors
        ),
        htmltools::tags$hr(),
        htmltools::tags$h6(tr("Preview")),
        tableOutput(ns("preview")),
        verbatimTextOutput(ns("preview_command"))
      )
    },
    observers = function(input, output, session, state, refresh) {
      preview <- reactive({
        upload <- input[[ns("upload")]]
        if (is.null(upload) || is.null(upload$datapath)) return(NULL)
        delimiter <- delimiter_code(input[[ns("delimiter")]] %||% "auto")
        preview_import_file(
          upload$datapath,
          delimiter = delimiter,
          header = isTRUE(input[[ns("header")]]),
          rows = state$options$import_preview_rows %||% 20L
        )
      })

      output[[ns("preview")]] <- renderTable({
        result <- preview()
        if (is.null(result)) return(NULL)
        if (!isTRUE(result$ok)) return(NULL)
        utils::head(result$data, state$options$import_preview_rows %||% 20L)
      }, rownames = FALSE, striped = TRUE, bordered = TRUE)

      output[[ns("preview_command")]] <- renderText({
        result <- preview()
        if (is.null(result) || !isTRUE(result$ok)) {
          if (!is.null(result) && !is.null(result$error)) return(result$error)
          return(tr("Choose a file to see the preview."))
        }
        types <- paste(names(result$types), result$types, sep = " = ",
                       collapse = ", ")
        paste0(tr("Proposed types: "), types)
      })

      observeEvent(input[[ns("delimiter")]], {
        if (!identical(state$current_dialog, id)) return()
        refresh()
      }, ignoreInit = TRUE)
    },
    on_ok = function(input, state) {
      upload <- input[[ns("upload")]]
      if (is.null(upload) || is.null(upload$datapath)) {
        return(list(error = tr("You must choose a file to import.")))
      }
      name <- trim_blanks(input[[ns("dsname")]] %||% "")
      if (!is_valid_name(name)) {
        return(list(error = sprintf(tr('"%s" is not a valid name.'), name)))
      }
      if (exists(name, envir = state$env, inherits = FALSE)) {
        return(list(error = sprintf(
          tr("An object named '%s' already exists. Choose another name."), name
        )))
      }

      stored <- store_import_file(upload$datapath, upload$name)
      if (is.null(stored)) {
        return(list(error = tr("The uploaded file could not be stored.")))
      }

      extension <- tolower(tools::file_ext(stored))
      header <- isTRUE(input[[ns("header")]])
      strings_as_factors <- isTRUE(input[[ns("stringsAsFactors")]])
      if (extension %in% c("xlsx", "xls")) {
        command <- cmd_import_excel(
          name, stored, sheet = 1L, header = header,
          stringsAsFactors = strings_as_factors
        )
      } else {
        delimiter <- input[[ns("delimiter")]] %||% "auto"
        if (identical(delimiter, "auto")) {
          delimiter <- detect_delimiter(stored)
        } else {
          delimiter <- delimiter_code(delimiter)
        }
        command <- read_text_command(
          dsname = name,
          header = header,
          stringsAsFactors = strings_as_factors,
          delimiter = "other",
          other = delimiter_source(delimiter),
          missing = "NA",
          decimal = "period",
          location = "local",
          path = stored
        )
      }

      list(
        commands = command,
        activate_dataset = name,
        tab = "Data",
        memory = list(
          dsname = name,
          header = header,
          delimiter = input[[ns("delimiter")]] %||% "auto",
          stringsAsFactors = strings_as_factors
        )
      )
    }
  )
}

# Grid helpers ---------------------------------------------------------------

#' Data frame shown in the grid with a stable row id
#'
#' DT returns row indices relative to the filtered view.  A hidden `.row_id`
#' column keeps the mapping back to the original rows stable.
#' @keywords internal
data_grid_frame <- function(df) {
  if (is.null(df)) return(NULL)
  grid <- df
  grid$.row_id <- seq_len(nrow(df))
  grid
}

#' Map selected grid rows back to original row numbers
#' @keywords internal
grid_rows_to_data <- function(grid, selected) {
  if (is.null(grid) || length(selected) == 0L) return(integer())
  if (!".row_id" %in% names(grid)) return(as.integer(selected))
  ids <- grid$.row_id[as.integer(selected)]
  as.integer(ids[!is.na(ids)])
}

#' Column order in use for a data set
#'
#' A saved order is validated against the current columns: a column added
#' later is appended instead of disappearing, and a dropped column is ignored.
#' @keywords internal
column_order_current <- function(state, df, dataset_name = active_dataset(state)) {
  if (is.null(df)) return(character())
  columns <- names(df)
  saved <- if (is.null(dataset_name)) NULL else {
    column_order_saved(state, dataset_name)
  }
  column_order_normalize(saved %||% columns, columns)
}

#' Apply the view order to a grid frame
#'
#' `.row_id` stays last: the DT callback and the hidden-column definition both
#' rely on it being the final column.
#' @keywords internal
data_order_columns <- function(grid, order) {
  if (is.null(grid) || ncol(grid) == 0L) return(grid)
  ordinary <- setdiff(names(grid), ".row_id")
  ordered <- column_order_normalize(order, ordinary)
  keep <- c(ordered, if (".row_id" %in% names(grid)) ".row_id")
  grid[, keep, drop = FALSE]
}

#' Columns the cell editor cannot round-trip safely
#'
#' Date-time and list columns would lose their time zone or their structure in
#' the grid, so the editor marks them read-only instead of pretending to edit
#' them.  The inspector still offers the targeted column actions.
#' @keywords internal
editor_readonly_columns <- function(df) {
  if (is.null(df) || ncol(df) == 0L) return(character())
  names(df)[vapply(df, function(x) {
    inherits(x, c("POSIXct", "POSIXlt")) || is.list(x)
  }, logical(1))]
}

#' Why an Apply click cannot use the editor
#'
#' A single place for the three conditions that keep a stale editor from
#' writing cells: the view must be Edit, the editor must belong to the active
#' data set and the stamp must be the current render.  `NULL` means the editor
#' can be applied.
#' @keywords internal
editor_apply_error <- function(mode, context, stamp, token, active) {
  if (!identical(mode, "edit")) {
    return(tr("Apply changes is only available in Edit mode."))
  }
  if (is.null(context) || !identical(context$dataset, active)) {
    return(tr("The editor belongs to another data set. Open Edit again."))
  }
  if (!nzchar(stamp %||% "") || !identical(stamp, token)) {
    return(tr("The data changed since the editor opened. Open Edit again."))
  }
  NULL
}

#' Is a column date-like?
#'
#' The Data Studio swaps its text filter for the date range only on these
#' columns.  `POSIXlt` is included because `read.table()` and packages still
#' produce it.
#' @keywords internal
date_column <- function(x) {
  inherits(x, c("Date", "POSIXct", "POSIXlt"))
}

#' Rows kept by a date range
#'
#' The range is inclusive at both ends and compares calendar dates, so a
#' `POSIXct` column is filtered by the day the user sees.  A missing end keeps
#' the range open; an empty range keeps every row.
#'
#' @param x A `Date`, `POSIXct` or `POSIXlt` vector.
#' @param range One or two dates, or `NULL`.
#' @return A logical vector, one per element of `x`.
#' @keywords internal
date_range_keep <- function(x, range) {
  keep <- rep(TRUE, length(x))
  if (is.null(range) || length(range) == 0L) return(keep)
  range <- suppressWarnings(as.Date(range))
  range <- range[!is.na(range)]
  if (length(range) == 0L) return(keep)
  dates <- suppressWarnings(as.Date(x))
  keep <- keep & !is.na(dates)
  keep <- keep & dates >= min(range)
  if (length(range) > 1L) keep <- keep & dates <= max(range)
  keep
}

#' Row-selection callback for the Data Studio grid
#'
#' DT's built-in selection is not reliable across DataTables releases when the
#' table lives in a dynamically rendered container.  The callback records the
#' hidden `.row_id` of the clicked rows and sends the original row numbers to
#' Shiny, so a view filter never changes what a selection means.
#' @keywords internal
grid_selection_callback <- function() {
  # DT wraps this code in `function(table) { ... }` itself, so the body only.
  DT::JS(
    "table.on('click', 'tbody tr', function(e) {",
    "  var $tr = $(this);",
    "  if (e.ctrlKey || e.metaKey) {",
    "    $tr.toggleClass('rcmdr-row-selected');",
    "  } else {",
    "    $(table.table().body()).find('tr.rcmdr-row-selected')",
    "      .removeClass('rcmdr-row-selected');",
    "    $tr.addClass('rcmdr-row-selected');",
    "  }",
    "  var ids = [];",
    "  table.rows('.rcmdr-row-selected').every(function() {",
    "    var data = this.data();",
    "    ids.push(data[data.length - 1]);",
    "  });",
    "  Shiny.setInputValue('data_grid_selection', ids,",
    "    {priority: 'event'});",
    "});"
  )
}

#' Open a dialog with prefilled memory
#' @keywords internal
open_dialog_memory <- function(state, id, memory = list()) {
  if (!is.function(state$open_dialog)) return(invisible(FALSE))
  spec <- get_dialog_spec(id)
  if (is.null(spec)) return(invisible(FALSE))
  set_dialog_memory(state, id, memory)
  state$open_dialog(id)
  invisible(TRUE)
}

