#' Inspector card for the selected column
#' @keywords internal
data_inspector_ui <- function(profile) {
  if (is.null(profile)) {
    return(empty_state(
      tr("No column selected"),
      tr("Choose a column in the grid or in the list above to see its profile.")
    ))
  }

  stats_ui <- if (!is.null(profile$stats)) {
    htmltools::tags$dl(
      class = "rcmdr-dl",
      htmltools::tags$dt(tr("Minimum")),
      htmltools::tags$dd(format(profile$stats$min, digits = 4)),
      htmltools::tags$dt(tr("Maximum")),
      htmltools::tags$dd(format(profile$stats$max, digits = 4)),
      htmltools::tags$dt(tr("Mean")),
      htmltools::tags$dd(format(profile$stats$mean, digits = 4)),
      htmltools::tags$dt(tr("Median")),
      htmltools::tags$dd(format(profile$stats$median, digits = 4)),
      htmltools::tags$dt(tr("SD")),
      htmltools::tags$dd(format(profile$stats$sd, digits = 4)),
      htmltools::tags$dt(tr("Q1 - Q3")),
      htmltools::tags$dd(sprintf("%s - %s",
                                 format(profile$stats$q1, digits = 4),
                                 format(profile$stats$q3, digits = 4)))
    )
  } else if (!is.null(profile$levels)) {
    htmltools::tags$table(
      class = "table table-sm rcmdr-table",
      htmltools::tags$thead(
        htmltools::tags$tr(
          htmltools::tags$th(tr("Value")),
          htmltools::tags$th(tr("Count"))
        )
      ),
      htmltools::tags$tbody(
        lapply(utils::head(profile$levels, 10L), function(row) {
          htmltools::tags$tr(
            htmltools::tags$td(row$value),
            htmltools::tags$td(row$count)
          )
        })
      )
    )
  } else {
    note(tr("No values to summarise."))
  }

  htmltools::tags$div(
    class = "rcmdr-data-inspector",
    htmltools::tags$h6(profile$variable),
    note(sprintf("%s - %s", profile$class, profile$type)),
    if (nzchar(profile$label %||% "")) {
      note(htmltools::tags$strong(profile$label))
    },
    if (nzchar(profile$units %||% "")) {
      note(sprintf(tr("Units: %s"), profile$units))
    },
    note(sprintf(tr("%d values, %d missing, %d unique"),
                 profile$n, profile$missing, profile$unique)),
    stats_ui,
    if (!is.null(profile$histogram) || !is.null(profile$levels)) {
      htmltools::tags$div(
        class = "rcmdr-profile-plot",
        plotOutput("data_profile_plot", height = "170px")
      )
    }
  )
}

#' Missingness bar
#' @keywords internal
data_missingness_ui <- function(table) {
  if (is.null(table) || nrow(table) == 0L) return(NULL)
  htmltools::tags$details(
    class = "rcmdr-section-card rcmdr-missingness",
    htmltools::tags$summary(tr("Missing values")),
    htmltools::tags$div(
      class = "rcmdr-section-body",
      lapply(seq_len(nrow(table)), function(i) {
        row <- table[i, , drop = FALSE]
        htmltools::tags$div(
          class = "rcmdr-missing-row",
          htmltools::tags$span(class = "rcmdr-missing-name", row$variable),
          htmltools::tags$div(
            class = "progress",
            htmltools::tags$div(
              class = "progress-bar bg-warning",
              role = "progressbar",
              style = sprintf("width: %.1f%%", row$percent),
              `aria-valuenow` = sprintf("%.1f", row$percent),
              `aria-valuemin` = "0", `aria-valuemax` = "100"
            )
          ),
          htmltools::tags$span(
            class = "rcmdr-missing-value",
            sprintf("%d (%.1f%%)", row$missing, row$percent)
          )
        )
      })
    )
  )
}

# Data Studio dialogs --------------------------------------------------------
#
# Structural operations use the standard dialog runtime instead of ad-hoc
# modals.  That gives them command preview, presets, validation and the same
# OK/Apply/Reset lifecycle as every other command in the application.

data_add_column_dialog <- function() {
  id <- "dataAddColumn"
  ns <- function(x) paste0(id, "_", x)
  defaults <- list(name = "new_column", expression = "")

  dialog_spec(
    id = id, title = tr("Add column"), help = "data.frame",
    ui = function(state, memory) {
      m <- utils::modifyList(defaults, memory %||% list())
      htmltools::tagList(
        entry_input(ns("name"), tr("Column name"), m$name),
        entry_input(
          ns("expression"), tr("Expression (optional)"),
          m$expression,
          placeholder = tr("e.g. x / y")
        ),
        help_text(tr(
          "The expression is evaluated in the active data set. Leave it empty to create a column of missing values."
        ))
      )
    },
    on_ok = function(input, state) {
      if (is.null(active_dataset(state))) {
        return(list(error = tr("There is no active data set.")))
      }
      name <- trim_blanks(input[[ns("name")]] %||% "")
      if (!is_valid_name(name)) {
        return(list(error = tr("Enter a valid column name.")))
      }
      if (name %in% names(dataset(state))) {
        return(list(error = tr("A column with that name already exists.")))
      }
      expression <- trim_blanks(input[[ns("expression")]] %||% "")
      checkpoint_create(state, tr("Before adding a column"))
      list(
        commands = cmd_add_column(
          active_dataset(state), name,
          expression = if (nzchar(expression)) expression else NULL
        ),
        activate_dataset = active_dataset(state),
        memory = list(name = name, expression = expression)
      )
    }
  )
}

data_duplicate_column_dialog <- function() {
  id <- "dataDuplicateColumn"
  ns <- function(x) paste0(id, "_", x)
  defaults <- list(variable = NULL, name = "")

  dialog_spec(
    id = id, title = tr("Duplicate column"), help = "data.frame",
    ui = function(state, memory) {
      m <- utils::modifyList(defaults, memory %||% list())
      variables <- names(dataset(state) %||% data.frame())
      selected <- if (!is.null(m$variable) && m$variable %in% variables) {
        m$variable
      } else {
        variables[[1L]] %||% NULL
      }
      htmltools::tagList(
        combo_input(ns("variable"), tr("Column to duplicate"),
                    stats::setNames(variables, variables), selected = selected),
        entry_input(
          ns("name"), tr("New column name"),
          m$name %||% if (!is.null(selected)) paste0(selected, "_copy") else ""
        )
      )
    },
    on_ok = function(input, state) {
      if (is.null(active_dataset(state))) {
        return(list(error = tr("There is no active data set.")))
      }
      variable <- input[[ns("variable")]] %||% ""
      name <- trim_blanks(input[[ns("name")]] %||% "")
      if (!variable %in% names(dataset(state))) {
        return(list(error = tr("Select a column to duplicate.")))
      }
      if (!is_valid_name(name) || name %in% names(dataset(state))) {
        return(list(error = tr("Enter a new, valid column name.")))
      }
      checkpoint_create(state, tr("Before duplicating a column"))
      list(
        commands = cmd_duplicate_column(active_dataset(state), variable, name),
        activate_dataset = active_dataset(state),
        memory = list(variable = variable, name = name)
      )
    }
  )
}

data_column_type_dialog <- function() {
  id <- "dataColumnType"
  ns <- function(x) paste0(id, "_", x)
  defaults <- list(variable = NULL, type = "numeric")

  dialog_spec(
    id = id, title = tr("Change column type"), help = "data.frame",
    ui = function(state, memory) {
      m <- utils::modifyList(defaults, memory %||% list())
      variables <- names(dataset(state) %||% data.frame())
      selected <- if (!is.null(m$variable) && m$variable %in% variables) {
        m$variable
      } else {
        variables[[1L]] %||% NULL
      }
      htmltools::tagList(
        combo_input(ns("variable"), tr("Column"),
                    stats::setNames(variables, variables), selected = selected),
        radio_input(
          ns("type"), tr("New type"),
          c("Numeric" = "numeric", "Factor" = "factor",
            "Character" = "character", "Logical" = "logical",
            "Date" = "date"),
          m$type
        ),
        help_text(tr(
          "Converting a factor to numeric uses as.numeric(as.character(x)), so the factor levels are not interpreted as codes."
        ))
      )
    },
    on_ok = function(input, state) {
      if (is.null(active_dataset(state))) {
        return(list(error = tr("There is no active data set.")))
      }
      variable <- input[[ns("variable")]] %||% ""
      if (!variable %in% names(dataset(state))) {
        return(list(error = tr("Select a column.")))
      }
      type <- input[[ns("type")]] %||% "numeric"
      checkpoint_create(state, tr("Before changing a column type"))
      list(
        commands = cmd_set_column_type(active_dataset(state), variable, type),
        activate_dataset = active_dataset(state),
        memory = list(variable = variable, type = type)
      )
    }
  )
}

data_subset_dialog <- function() {
  id <- "dataCreateSubset"
  ns <- function(x) paste0(id, "_", x)

  dialog_spec(
    id = id, title = tr("Create subset from selection"), help = "subset",
    ui = function(state, memory) {
      base <- active_dataset(state) %||% "Dataset"
      htmltools::tagList(
        entry_input(ns("name"), tr("New data set name"),
                    memory$name %||% paste0(base, "Subset")),
        help_text(tr(
          "The subset is generated as an R command and appears in the script log."
        )),
        note(selection_summary(state))
      )
    },
    on_ok = function(input, state) {
      name <- trim_blanks(input[[ns("name")]] %||% "")
      if (!is_valid_name(name)) {
        return(list(error = tr("Enter a valid data set name.")))
      }
      command <- selection_subset_command(state, name)
      if (is.null(command)) {
        return(list(error = tr("Select rows, columns or a filter first.")))
      }
      list(
        commands = command,
        activate_dataset = name,
        tab = "Data",
        memory = list(name = name)
      )
    }
  )
}

data_delete_rows_dialog <- function() {
  id <- "dataDeleteRows"
  ns <- function(x) paste0(id, "_", x)

  dialog_spec(
    id = id, title = tr("Delete rows"), help = "data.frame",
    ui = function(state, memory) {
      rows <- memory$rows %||% data_selection(state)$rows
      htmltools::tagList(
        htmltools::tags$p(sprintf(
          tr("Delete %d selected row(s) from %s?"),
          length(rows), active_dataset(state) %||% tr("the data set")
        )),
        htmltools::tags$div(
          style = "display: none;",
          textInput(ns("rows"), NULL, value = paste(rows, collapse = ","))
        ),
        help_text(tr(
          "A checkpoint is created before the rows are removed. The deletion is recorded as an R command."
        ))
      )
    },
    on_ok = function(input, state) {
      raw <- input[[ns("rows")]] %||% ""
      if (!nzchar(raw)) {
        raw <- paste((state$data_selection %||% list())$rows %||% integer(),
                     collapse = ",")
      }
      rows <- suppressWarnings(as.integer(strsplit(raw, ",", fixed = TRUE)[[1L]]))
      rows <- rows[!is.na(rows)]
      if (length(rows) == 0L) {
        return(list(error = tr("Select one or more rows first.")))
      }
      checkpoint_create(state, tr("Before deleting rows"))
      list(
        commands = cmd_delete_rows(active_dataset(state), rows),
        activate_dataset = active_dataset(state),
        tab = "Data",
        memory = list(rows = rows)
      )
    }
  )
}

data_checkpoints_dialog <- function() {
  id <- "dataCheckpoints"
  ns <- function(x) paste0(id, "_", x)

  dialog_spec(
    id = id, title = tr("Session checkpoints"), help = "data.frame",
    preview = FALSE,
    ui = function(state, memory) {
      table <- checkpoint_list(state)
      if (nrow(table) == 0L) {
        return(empty_state(
          tr("No checkpoints"),
          tr("A checkpoint is created before every data change.")
        ))
      }
      htmltools::tagList(
        help_text(tr(
          "Checkpoints are session snapshots. Restoring one does not add a command to the script log."
        )),
        tableOutput(ns("table")),
        selectInput(
          ns("checkpoint"), tr("Checkpoint"),
          choices = stats::setNames(
            table$id,
            sprintf("%s - %s (%s)", table$time, table$label, table$size)
          ),
          selected = memory$checkpoint %||% table$id[[1L]]
        )
      )
    },
    observers = function(input, output, session, state, refresh) {
      output[[ns("table")]] <- renderTable({
        refresh()
        if (!identical(state$current_dialog, id)) return(NULL)
        checkpoint_list(state)
      }, striped = TRUE, bordered = TRUE, spacing = "s")
    },
    on_ok = function(input, state) {
      checkpoint_id <- input[[ns("checkpoint")]] %||% ""
      if (!nzchar(checkpoint_id)) return(list(error = tr("No checkpoint selected.")))
      if (!checkpoint_restore(state, checkpoint_id)) {
        return(list(error = tr("The checkpoint could not be restored.")))
      }
      list(
        tab = "Data",
        message = tr("Checkpoint restored."),
        memory = list(checkpoint = checkpoint_id)
      )
    }
  )
}

data_dictionary_dialog <- function() {
  id <- "dataDictionary"
  ns <- function(x) paste0(id, "_", x)

  dialog_spec(
    id = id, title = tr("Data dictionary"), help = "data.frame",
    preview = FALSE,
    ui = function(state, memory) {
      table <- dictionary_table(state)
      if (nrow(table) == 0L) {
        return(empty_state(tr("No active data set")))
      }
      variables <- table$variable
      selected <- memory$variable %||% variables[[1L]]
      if (!selected %in% variables) selected <- variables[[1L]]
      meta <- variable_label(state, active_dataset(state), selected)
      htmltools::tagList(
        tableOutput(ns("table")),
        selectInput(ns("variable"), tr("Variable"),
                    choices = stats::setNames(variables, variables),
                    selected = selected),
        textInput(ns("label"), tr("Label"), value = meta$label %||% ""),
        textInput(ns("units"), tr("Units"), value = meta$units %||% ""),
        textInput(ns("description"), tr("Description"),
                  value = meta$description %||% ""),
        fileInput(
          ns("upload"), tr("Import dictionary (CSV)"),
          accept = ".csv"
        ),
        action_row(
          downloadButton("download_dictionary_csv", tr("Export CSV"),
                         class = "btn-sm btn-outline-secondary"),
          if (requireNamespace("yaml", quietly = TRUE)) {
            downloadButton("download_dictionary_yaml", tr("Export YAML"),
                           class = "btn-sm btn-outline-secondary")
          }
        )
      )
    },
    observers = function(input, output, session, state, refresh) {
      output[[ns("table")]] <- renderTable({
        refresh()
        if (!identical(state$current_dialog, id)) return(NULL)
        dictionary_table(state)
      }, striped = TRUE, bordered = TRUE, spacing = "s")

      observeEvent(input[[ns("variable")]], {
        if (!identical(state$current_dialog, id)) return()
        variable <- input[[ns("variable")]] %||% ""
        if (!nzchar(variable)) return()
        meta <- variable_label(state, active_dataset(state), variable)
        updateTextInput(session, ns("label"), value = meta$label %||% "")
        updateTextInput(session, ns("units"), value = meta$units %||% "")
        updateTextInput(session, ns("description"),
                        value = meta$description %||% "")
      }, ignoreInit = TRUE)

      observeEvent(input[[ns("upload")]], {
        if (!identical(state$current_dialog, id)) return()
        upload <- input[[ns("upload")]]
        if (is.null(upload) || is.null(upload$datapath)) return()
        table <- tryCatch(
          utils::read.csv(upload$datapath, stringsAsFactors = FALSE),
          error = function(e) NULL
        )
        if (is.null(table) || !all(c("variable", "label") %in% names(table))) {
          showNotification(
            tr("The dictionary CSV needs at least the variable and label columns."),
            type = "error", duration = 6
          )
          return()
        }
        for (i in seq_len(nrow(table))) {
          variable <- table$variable[[i]]
          if (!variable %in% names(dataset(state))) next
          label <- table$label[[i]] %||% ""
          units <- if ("units" %in% names(table)) table$units[[i]] %||% "" else ""
          description <- if ("description" %in% names(table)) {
            table$description[[i]] %||% ""
          } else ""
          for (command in cmd_set_variable_label(
            active_dataset(state), variable,
            label = label, units = units, description = description
          )) {
            run_command(state, command, source = "data")
          }
          set_variable_label(state, active_dataset(state), variable,
                             label = label, units = units,
                             description = description)
        }
        refresh()
        showNotification(tr("Dictionary imported."), type = "message",
                         duration = 4)
      }, ignoreInit = TRUE)
    },
    on_ok = function(input, state) {
      if (is.null(active_dataset(state))) {
        return(list(error = tr("There is no active data set.")))
      }
      variable <- input[[ns("variable")]] %||% ""
      if (!nzchar(variable) || !variable %in% names(dataset(state))) {
        return(list(error = tr("Select a variable.")))
      }
      label <- trim_blanks(input[[ns("label")]] %||% "")
      units <- trim_blanks(input[[ns("units")]] %||% "")
      description <- trim_blanks(input[[ns("description")]] %||% "")
      set_variable_label(state, active_dataset(state), variable,
                         label = label, units = units,
                         description = description)
      list(
        commands = cmd_set_variable_label(
          active_dataset(state), variable,
          label = label, units = units, description = description
        ),
        activate_dataset = active_dataset(state),
        tab = "Data",
        message = tr("Dictionary updated."),
        memory = list(variable = variable)
      )
    }
  )
}

#' Data Studio dialog catalogue
#' @keywords internal
data_studio_dialogs <- function() {
  list(
    dataAddColumn = data_add_column_dialog(),
    dataDuplicateColumn = data_duplicate_column_dialog(),
    dataColumnType = data_column_type_dialog(),
    dataCreateSubset = data_subset_dialog(),
    dataDeleteRows = data_delete_rows_dialog(),
    dataCheckpoints = data_checkpoints_dialog(),
    dataDictionary = data_dictionary_dialog()
  )
}
